#!/usr/bin/env bash

pid_process_state() {
  local pid=${1:-} state
  if [[ ! ${pid} =~ ^[1-9][0-9]*$ ]]; then
    printf '%s\n' absent
    return 0
  fi
  state=$(ps -o stat= -p "${pid}" 2>/dev/null | awk 'NF {print $1; exit}') || state=
  case ${state:0:1} in
    Z) printf '%s\n' zombie ;;
    '') printf '%s\n' absent ;;
    *) printf '%s\n' live ;;
  esac
}
